 }
 button { font: inherit; }
 .page-shell { width: min(1120px, calc(100% - 72px)); margin: 0 auto; }
 .topbar { height: 80px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid rgba(213, 194, 182, .55); }
+.top-actions { display: flex; align-items: center; gap: 9px; }
