import math, struct, zlib
from pathlib import Path

OUT = Path('icons')
OUT.mkdir(exist_ok=True)

def png_bytes(size):
    scale = 3
    n = size * scale
    bg = (251, 246, 241, 255)
    rose = (207, 98, 93, 255)
    cream = (255, 253, 250, 255)
    sage = (232, 238, 232, 255)
    pixels = bytearray(bg * (n * n))
    def paint(x, y, color):
        if 0 <= x < n and 0 <= y < n:
            i = (y * n + x) * 4
            pixels[i:i+4] = bytes(color)
    def rounded_rect(x0, y0, x1, y1, radius, color):
        for y in range(y0, y1):
            for x in range(x0, x1):
                cx = min(max(x, x0 + radius), x1 - radius - 1)
                cy = min(max(y, y0 + radius), y1 - radius - 1)
                if (x-cx)**2 + (y-cy)**2 <= radius**2:
                    paint(x, y, color)
    def line(x0, y0, x1, y1, width, color):
        minx, maxx = max(0, min(x0,x1)-width), min(n, max(x0,x1)+width+1)
        miny, maxy = max(0, min(y0,y1)-width), min(n, max(y0,y1)+width+1)
        dx, dy = x1-x0, y1-y0
        denom = dx*dx + dy*dy
        for y in range(miny, maxy):
            for x in range(minx, maxx):
                t = max(0, min(1, ((x-x0)*dx + (y-y0)*dy) / denom))
                px, py = x0+t*dx, y0+t*dy
                if (x-px)**2 + (y-py)**2 <= width*width:
                    paint(x, y, color)
    def ring(cx, cy, radius, width, color):
        for y in range(max(0,cy-radius-width), min(n,cy+radius+width+1)):
            for x in range(max(0,cx-radius-width), min(n,cx+radius+width+1)):
                d = math.hypot(x-cx, y-cy)
                if radius-width/2 <= d <= radius+width/2:
                    paint(x,y,color)
    rounded_rect(24*scale, 24*scale, (size-24)*scale, (size-24)*scale, 54*scale, rose)
    line(72*scale, 72*scale, 132*scale, 132*scale, 9*scale, cream)
    line(132*scale, 72*scale, 72*scale, 132*scale, 9*scale, cream)
    ring(132*scale, 132*scale, 22*scale, 8*scale, sage)
    # 3x supersampling downsampled by averaging each pixel's samples.
    raw = bytearray()
    for y in range(size):
        raw.append(0)
        for x in range(size):
            totals = [0,0,0,0]
            for sy in range(scale):
                for sx in range(scale):
                    i = (((y*scale+sy)*n)+(x*scale+sx))*4
                    for c in range(4): totals[c] += pixels[i+c]
            raw.extend(v // (scale*scale) for v in totals)
    def chunk(kind, data):
        return struct.pack('!I', len(data)) + kind + data + struct.pack('!I', zlib.crc32(kind+data) & 0xffffffff)
    return b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('!2I5B',size,size,8,6,0,0,0)) + chunk(b'IDAT', zlib.compress(bytes(raw), 9)) + chunk(b'IEND', b'')

for size in (192, 512):
    (OUT / f'icon-{size}.png').write_bytes(png_bytes(size))
